<section class="card border-0 shadow-sm"><div class="card-header bg-white"><h2 class="h6 fw-bold mb-0">Find a student</h2></div><div class="card-body"><form method="get" class="row g-3 align-items-end mb-3"><div class="col-12 col-md-4"><label class="form-label" for="schoolYear">School year</label><select class="form-select" name="school_year" id="schoolYear"><?php foreach ($years as $year): ?><option value="<?= html_escape($year); ?>" <?= $year === $school_year ? 'selected' : ''; ?>><?= html_escape($year); ?></option><?php endforeach; ?></select></div><div class="col-12 col-md-6"><label class="form-label" for="studentSearch">Student name, number, or LRN</label><input class="form-control" id="studentSearch" name="q" value="<?= html_escape($search); ?>"></div><div class="col-12 col-md-2"><button class="btn btn-primary w-100">Search</button></div></form>
<div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Student no.</th><th>Student</th><th>Grade</th><th>Section</th><th>School year</th><th></th></tr></thead><tbody><?php if (!$enrollments): ?><tr><td colspan="6" class="text-center text-secondary py-4">No enrollments found for this school year.</td></tr><?php else: foreach ($enrollments as $enrollment): ?><tr><td><?= html_escape($enrollment->student_no ?: '—'); ?></td><td><?= html_escape(trim($enrollment->first_name . ' ' . $enrollment->middle_name . ' ' . $enrollment->last_name)); ?></td><td><?= html_escape($enrollment->grade_level); ?></td><td><?= html_escape($enrollment->section_name ?: $enrollment->section ?: 'Not assigned'); ?></td><td><?= html_escape($enrollment->academic_year); ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('academic/report-cards/' . (int) $enrollment->enrollment_id); ?>">View report card</a></td></tr><?php endforeach; endif; ?></tbody></table></div></div></section>
